    pub const ALL: &'static [Tool] = &[
        Tool::Read,
        Tool::Glob,
        Tool::Grep,
        Tool::Write,
        Tool::Patch,
        Tool::Delete,
        Tool::Shell,
        Tool::Git,
        Tool::Gate,
        Tool::Fetch,
    ];

    pub fn as_str(self) -> &'static str {
        match self {
            Tool::Read => "read",
            Tool::Glob => "glob",
            Tool::Grep => "grep",
            Tool::Write => "write",
            Tool::Patch => "patch",
            Tool::Delete => "delete",
            Tool::Shell => "shell",
            Tool::Git => "git",
            Tool::Gate => "gate",
            Tool::Fetch => "fetch",
        }
    }

    pub fn parse(text: &str) -> Result<Tool> {
        Tool::ALL
            .iter()
            .copied()
            .find(|tool| tool.as_str() == text)
            .ok_or_else(|| Error::unbound("tool", format!("`{text}` is not a tool")))
    }

    /// `(required, all)` parameter names, for the wire schema.
