            Tool::Glob => (&["pattern"], &["pattern"]),
            Tool::Grep => (&["pattern"], &["pattern", "path"]),
            Tool::Write => (&["path", "content"], &["path", "content"]),
            Tool::Patch => (&["path", "expect", "replace"], &["path", "expect", "replace"]),
            Tool::Delete => (&["path"], &["path"]),
            Tool::Shell => (&["command"], &["command", "timeout"]),
